/* CreativeHub — Shared Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

:root {
  --brand: #F02D00;
  --brand-dark: #c42400;
  --dark: #171717;
  --dark2: #222222;
  --dark3: #2e2e2e;
  --gray1: #444444;
  --gray2: #6b6b6b;
  --gray3: #9a9a9a;
  --gray4: #c8c8c8;
  --gray5: #e5e5e5;
  --gray6: #f5f5f5;
  --white: #ffffff;
  --radius-sm: 6px;
  --radius: 10px;
  --radius-lg: 16px;
  --shadow-sm: 0 1px 4px rgba(0,0,0,.08);
  --shadow: 0 4px 16px rgba(0,0,0,.10);
  --shadow-md: 0 8px 32px rgba(0,0,0,.14);
  --transition: 180ms ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', system-ui, sans-serif;
  background: var(--white);
  color: var(--dark);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { display: block; max-width: 100%; }
button { cursor: pointer; font-family: inherit; }

/* ─── Promo Banner ─── */
.promo-banner {
  background: var(--dark);
  color: var(--white);
  text-align: center;
  padding: 10px 1rem;
  font-size: .85rem;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .75rem;
  position: relative;
}
.promo-banner strong { color: var(--brand); }
.promo-banner .countdown { display: inline-flex; gap: .3rem; font-weight: 700; }
.promo-banner .countdown span {
  background: var(--brand);
  border-radius: 4px;
  padding: 1px 6px;
  font-size: .8rem;
  min-width: 28px;
  text-align: center;
}
.promo-banner .close-btn {
  position: absolute;
  right: 1rem;
  top: 50%;
  transform: translateY(-50%);
  background: none;
  border: none;
  color: var(--gray4);
  font-size: 1.1rem;
  line-height: 1;
  padding: 2px 6px;
  border-radius: 4px;
  transition: color var(--transition);
}
.promo-banner .close-btn:hover { color: var(--white); }

/* ─── Header / Nav ─── */
.site-header {
  background: var(--white);
  border-bottom: 1px solid var(--gray5);
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: var(--shadow-sm);
}
.nav-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
  height: 60px;
  display: flex;
  align-items: center;
  gap: 2rem;
}
.nav-logo {
  font-size: 1.25rem;
  font-weight: 900;
  color: var(--brand);
  white-space: nowrap;
  letter-spacing: -.02em;
}
.nav-logo span { color: var(--dark); }
.nav-links {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  list-style: none;
}
.nav-links a {
  font-size: .9rem;
  font-weight: 500;
  color: var(--dark);
  transition: color var(--transition);
}
.nav-links a:hover, .nav-links a.active { color: var(--brand); }
.nav-search {
  flex: 1;
  max-width: 340px;
  position: relative;
}
.nav-search input {
  width: 100%;
  padding: 8px 14px 8px 36px;
  border: 1.5px solid var(--gray5);
  border-radius: 20px;
  font-size: .875rem;
  outline: none;
  transition: border-color var(--transition);
  background: var(--gray6);
}
.nav-search input:focus { border-color: var(--brand); background: var(--white); }
.nav-search .search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--gray3);
  pointer-events: none;
}
.nav-actions {
  display: flex;
  align-items: center;
  gap: .75rem;
  margin-left: auto;
}
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .4rem;
  padding: 8px 18px;
  border-radius: var(--radius-sm);
  font-size: .875rem;
  font-weight: 600;
  border: 2px solid transparent;
  transition: all var(--transition);
  white-space: nowrap;
}
.btn-ghost {
  background: none;
  border-color: transparent;
  color: var(--dark);
}
.btn-ghost:hover { color: var(--brand); }
.btn-outline {
  background: none;
  border-color: var(--dark);
  color: var(--dark);
}
.btn-outline:hover { border-color: var(--brand); color: var(--brand); }
.btn-primary {
  background: var(--brand);
  border-color: var(--brand);
  color: var(--white);
}
.btn-primary:hover { background: var(--brand-dark); border-color: var(--brand-dark); }
.btn-dark {
  background: var(--dark);
  border-color: var(--dark);
  color: var(--white);
}
.btn-dark:hover { background: var(--dark2); }

/* Mobile Nav Toggle */
.nav-hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  padding: 4px;
  margin-left: auto;
}
.nav-hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--dark);
  border-radius: 2px;
  transition: all var(--transition);
}
.mobile-nav {
  display: none;
  flex-direction: column;
  background: var(--white);
  border-top: 1px solid var(--gray5);
  padding: 1rem 1.5rem;
  gap: .75rem;
}
.mobile-nav.open { display: flex; }
.mobile-nav a {
  font-size: .95rem;
  font-weight: 500;
  padding: .4rem 0;
  border-bottom: 1px solid var(--gray6);
  color: var(--dark);
}
.mobile-nav a:last-child { border-bottom: none; }

/* ─── Course Card ─── */
.course-card {
  background: var(--white);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray5);
  transition: transform var(--transition), box-shadow var(--transition);
  display: flex;
  flex-direction: column;
}
.course-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
.course-card-img {
  width: 100%;
  aspect-ratio: 16/9;
  object-fit: cover;
  background: var(--gray5);
}
.course-card-body { padding: .875rem 1rem 1rem; flex: 1; display: flex; flex-direction: column; gap: .3rem; }
.course-card-title { font-size: .875rem; font-weight: 700; line-height: 1.3; color: var(--dark); }
.course-card-instructor { font-size: .775rem; color: var(--gray2); }
.course-card-meta { display: flex; align-items: center; gap: .5rem; font-size: .75rem; color: var(--gray2); flex-wrap: wrap; margin-top: auto; padding-top: .4rem; }
.course-card-rating { display: flex; align-items: center; gap: .2rem; color: var(--dark); font-weight: 600; }
.course-card-rating .star { color: #f59e0b; font-size: .8rem; }
.course-card-price { display: flex; align-items: baseline; gap: .4rem; padding-top: .3rem; }
.price-current { font-size: 1rem; font-weight: 800; color: var(--dark); }
.price-original { font-size: .8rem; color: var(--gray3); text-decoration: line-through; }
.badge-bestseller {
  display: inline-block;
  background: #fef3c7;
  color: #92400e;
  font-size: .65rem;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 3px;
  text-transform: uppercase;
  letter-spacing: .03em;
}
.badge-discount {
  display: inline-block;
  background: var(--brand);
  color: var(--white);
  font-size: .65rem;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 3px;
}
.badge-free {
  display: inline-block;
  background: #dcfce7;
  color: #166534;
  font-size: .65rem;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 3px;
  text-transform: uppercase;
}

/* ─── Section ─── */
.section { padding: 4rem 0; }
.section-sm { padding: 2.5rem 0; }
.container { max-width: 1280px; margin: 0 auto; padding: 0 1.5rem; }
.section-header { display: flex; align-items: baseline; justify-content: space-between; margin-bottom: 1.75rem; }
.section-title { font-size: 1.5rem; font-weight: 800; letter-spacing: -.02em; }
.section-link { font-size: .85rem; font-weight: 600; color: var(--brand); text-decoration: underline; text-underline-offset: 3px; }

/* ─── Carousel ─── */
.carousel-wrap { position: relative; }
.carousel-track-outer { overflow: hidden; }
.carousel-track {
  display: flex;
  gap: 1.25rem;
  transition: transform 350ms cubic-bezier(.4,0,.2,1);
}
.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--white);
  border: 1.5px solid var(--gray4);
  box-shadow: var(--shadow);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  color: var(--dark);
  transition: all var(--transition);
}
.carousel-arrow:hover { background: var(--brand); border-color: var(--brand); color: var(--white); }
.carousel-arrow.prev { left: -20px; }
.carousel-arrow.next { right: -20px; }
.carousel-arrow:disabled { opacity: .3; cursor: not-allowed; }
.carousel-dots { display: flex; justify-content: center; gap: .5rem; margin-top: 1.25rem; }
.carousel-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: var(--gray4);
  border: none;
  padding: 0;
  transition: background var(--transition), width var(--transition);
}
.carousel-dot.active { background: var(--brand); width: 22px; border-radius: 4px; }

/* ─── Footer ─── */
.site-footer {
  background: var(--dark);
  color: var(--gray4);
  padding: 3rem 0 1.5rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 2rem 1.5rem;
  margin-bottom: 2.5rem;
}
.footer-col h4 {
  font-size: .75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--white);
  margin-bottom: .875rem;
}
.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: .45rem; }
.footer-col ul li { font-size: .8rem; }
.footer-col ul li a { color: var(--gray3); transition: color var(--transition); }
.footer-col ul li a:hover { color: var(--white); }
.footer-bottom {
  border-top: 1px solid var(--dark3);
  padding-top: 1.5rem;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}
.footer-legal { display: flex; flex-wrap: wrap; gap: .75rem 1.5rem; }
.footer-legal a { font-size: .75rem; color: var(--gray3); transition: color var(--transition); }
.footer-legal a:hover { color: var(--white); }
.footer-brand { font-size: .85rem; font-weight: 700; color: var(--white); }
.footer-brand span { color: var(--brand); }
.footer-langs { display: flex; flex-wrap: wrap; gap: .4rem .75rem; }
.footer-langs a { font-size: .75rem; color: var(--gray3); transition: color var(--transition); }
.footer-langs a:hover { color: var(--white); }

/* Footer accordion for mobile */
.footer-acc-btn {
  display: none;
  width: 100%;
  text-align: left;
  background: none;
  border: none;
  color: var(--white);
  font-size: .75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .08em;
  padding: .5rem 0;
  cursor: pointer;
  justify-content: space-between;
  align-items: center;
}
.footer-acc-body { display: flex; flex-direction: column; gap: .45rem; }

/* ─── Responsive ─── */
@media (max-width: 1024px) {
  .carousel-arrow.prev { left: -10px; }
  .carousel-arrow.next { right: -10px; }
}
@media (max-width: 768px) {
  .nav-links, .nav-search, .nav-actions { display: none; }
  .nav-hamburger { display: flex; }
  .section { padding: 2.5rem 0; }
  .section-title { font-size: 1.25rem; }
  .footer-acc-btn { display: flex; }
  .footer-acc-body { display: none; }
  .footer-acc-body.open { display: flex; }
  .footer-col h4 { display: none; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 0; }
  .footer-col { border-bottom: 1px solid var(--dark3); padding: .5rem 0; }
}
@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
}

