<script>
document.addEventListener('DOMContentLoaded', () => {
  // Time filter pills
  document.querySelectorAll('#time-pills .filter-pill').forEach(pill => {
    pill.addEventListener('click', () => {
      document.querySelectorAll('#time-pills .filter-pill').forEach(p => p.classList.remove('active'));
      pill.classList.add('active');
      sortGallery();
    });
  });

  // Sort
  const sortSelect = document.getElementById('sort-select');
  sortSelect?.addEventListener('change', sortGallery);

  // Field filter
  const fieldSelect = document.getElementById('field-select');
  fieldSelect?.addEventListener('change', () => {
    const val = fieldSelect.value.toLowerCase();
    document.querySelectorAll('.masonry-item').forEach(item => {
      const field = (item.dataset.field || '').toLowerCase();
      item.style.display = (!val || field.includes(val)) ? '' : 'none';
    });
  });

  function sortGallery() {
    const grid = document.getElementById('masonry-grid');
    if (!grid) return;
    const sort = sortSelect?.value || 'featured';
    const items = Array.from(grid.querySelectorAll('.masonry-item'));
    items.sort((a, b) => {
      if (sort === 'liked') return parseInt(b.dataset.likes) - parseInt(a.dataset.likes);
      if (sort === 'viewed') return parseInt(b.dataset.views) - parseInt(a.dataset.views);
      return 0;
    });
    items.forEach(item => grid.appendChild(item));
  }

  // Load more
  document.getElementById('load-more-btn')?.addEventListener('click', function() {
    this.textContent = 'Loading…';
    setTimeout(() => { this.textContent = 'No more projects'; this.disabled = true; this.style.opacity = '.5'; }, 800);
  });
});
</script>
